return [
  {
    json: {
      chain: "Netto",
      dealerId: "demo-netto"
    }
  },
  {
    json: {
      chain: "REMA 1000",
      dealerId: "demo-rema"
    }
  },
  {
    json: {
      chain: "365discount",
      dealerId: "demo-365"
    }
  }
];

const raw = $json;

const price = raw.pricing?.price ?? null;
const advertisedBeforePrice =
  raw.pricing?.pre_price ?? null;

let quantityFrom =
  raw.quantity?.size?.from ?? null;

let quantityTo =
  raw.quantity?.size?.to ?? quantityFrom;

let originalUnit =
  raw.quantity?.unit?.symbol?.toLowerCase() ?? null;

const piecesFrom =
  raw.quantity?.pieces?.from ?? null;

const piecesTo =
  raw.quantity?.pieces?.to ?? piecesFrom;

const productName =
  raw.heading ??
  raw.name ??
  "Unknown product";

const description =
  raw.description ?? null;

const searchableText = [
  productName,
  description
]
  .filter(Boolean)
  .join(" ")
  .toLowerCase();

/*
 * Semantiske mængder i beskrivelsen har højere prioritet
 * end API'ets generelle pakkestørrelse.
 *
 * Eksempel:
 * "1 liter. 20-22 vaske. Pris pr. vask maks. 1,00"
 * skal sammenlignes per vask, ikke per liter.
 */
const washRangeMatch = searchableText.match(
  /(\d+(?:[.,]\d+)?)\s*(?:-|–|—|til)\s*(\d+(?:[.,]\d+)?)\s*vaske?\b/i
);

const singleWashMatch = searchableText.match(
  /(\d+(?:[.,]\d+)?)\s*vaske?\b/i
);

function parseDanishNumber(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const parsed = Number(
    String(value).replace(",", ".")
  );

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

if (washRangeMatch) {
  const parsedFrom =
    parseDanishNumber(washRangeMatch[1]);

  const parsedTo =
    parseDanishNumber(washRangeMatch[2]);

  if (
    parsedFrom !== null &&
    parsedTo !== null &&
    parsedFrom > 0 &&
    parsedTo > 0
  ) {
    quantityFrom = Math.min(parsedFrom, parsedTo);
    quantityTo = Math.max(parsedFrom, parsedTo);
    originalUnit = "vask";
  }
} else if (singleWashMatch) {
  const parsedWashes =
    parseDanishNumber(singleWashMatch[1]);

  if (
    parsedWashes !== null &&
    parsedWashes > 0
  ) {
    quantityFrom = parsedWashes;
    quantityTo = parsedWashes;
    originalUnit = "vask";
  }
}

/*
 * Genkend antal enheder, når tilbudsteksten udtrykkeligt
 * angiver en stk-pris.
 *
 * Eksempel:
 * "40-50 stk. Stk-pris maks. 1,73"
 */
const explicitlyPricedPerPiece =
  /\b(?:stk\.?\s*-?\s*pris|pris\s+pr\.?\s*stk\.?)\b/iu
    .test(searchableText);

const pieceRangeMatch = searchableText.match(
  /(\d+(?:[.,]\d+)?)\s*(?:-|–|—|til)\s*(\d+(?:[.,]\d+)?)\s*(?:stk\.?|styk(?:ker)?)\b/iu
);

const singlePieceMatch = searchableText.match(
  /(\d+(?:[.,]\d+)?)\s*(?:stk\.?|styk(?:ker)?)\b/iu
);

if (
  originalUnit !== "vask" &&
  explicitlyPricedPerPiece
) {
  if (pieceRangeMatch) {
    const parsedFrom =
      parseDanishNumber(pieceRangeMatch[1]);

    const parsedTo =
      parseDanishNumber(pieceRangeMatch[2]);

    if (
      parsedFrom !== null &&
      parsedTo !== null &&
      parsedFrom > 0 &&
      parsedTo > 0
    ) {
      quantityFrom =
        Math.min(parsedFrom, parsedTo);

      quantityTo =
        Math.max(parsedFrom, parsedTo);

      originalUnit = "stk";
    }
  } else if (singlePieceMatch) {
    const parsedPieces =
      parseDanishNumber(singlePieceMatch[1]);

    if (
      parsedPieces !== null &&
      parsedPieces > 0
    ) {
      quantityFrom = parsedPieces;
      quantityTo = parsedPieces;
      originalUnit = "stk";
    }
  }
}

/*
 * API'ets pieces-felt er autoritativt, når varen
 * allerede er angivet med en styk-enhed.
 *
 * Eksempel:
 * size.from = 1
 * unit.symbol = "pcs"
 * pieces.from = 40
 * pieces.to = 50
 *
 * Resultat: 40-50 stk., ikke én pakke.
 */
const numericPiecesFrom =
  piecesFrom !== null &&
  piecesFrom !== undefined
    ? Number(piecesFrom)
    : null;

const numericPiecesTo =
  piecesTo !== null &&
  piecesTo !== undefined
    ? Number(piecesTo)
    : numericPiecesFrom;

const sourceUsesPieceUnit = [
  "pcs",
  "pc",
  "stk",
  "st",
  "styk"
].includes(
  String(originalUnit ?? "")
    .toLowerCase()
);

if (
  originalUnit !== "vask" &&
  sourceUsesPieceUnit &&
  Number.isFinite(numericPiecesFrom) &&
  numericPiecesFrom > 1
) {
  quantityFrom =
    numericPiecesFrom;

  quantityTo =
    Number.isFinite(numericPiecesTo) &&
    numericPiecesTo >= numericPiecesFrom
      ? numericPiecesTo
      : numericPiecesFrom;

  originalUnit =
    "stk";
}

function normalizeQuantity(value, unit) {
  if (
    value === null ||
    value === undefined ||
    !unit
  ) {
    return null;
  }

  const numericValue = Number(value);

  if (
    !Number.isFinite(numericValue) ||
    numericValue <= 0
  ) {
    return null;
  }

  switch (unit) {
    case "g":
      return {
        value: numericValue / 1000,
        unit: "kg"
      };

    case "kg":
      return {
        value: numericValue,
        unit: "kg"
      };

    case "ml":
      return {
        value: numericValue / 1000,
        unit: "l"
      };

    case "cl":
      return {
        value: numericValue / 100,
        unit: "l"
      };

    case "dl":
      return {
        value: numericValue / 10,
        unit: "l"
      };

    case "l":
    case "liter":
      return {
        value: numericValue,
        unit: "l"
      };

    case "stk":
    case "st":
    case "pcs":
    case "vask":
    case "vaske":
      return {
        value: numericValue,
        unit: "pcs"
      };

    default:
      return {
        value: numericValue,
        unit
      };
  }
}

const normalizedFrom =
  normalizeQuantity(quantityFrom, originalUnit);

const normalizedTo =
  normalizeQuantity(quantityTo, originalUnit);

let unitPriceWorstCase = null;
let unitPriceBestCase = null;

let normalizedUnit =
  normalizedFrom?.unit ?? null;

if (
  price !== null &&
  normalizedFrom?.value > 0
) {
  // Den mindste mængde giver den højeste enhedspris.
  unitPriceWorstCase = Number(
    (
      Number(price) /
      normalizedFrom.value
    ).toFixed(4)
  );

  const bestQuantity =
    normalizedTo?.value ??
    normalizedFrom.value;

  unitPriceBestCase = Number(
    (
      Number(price) /
      bestQuantity
    ).toFixed(4)
  );
} else if (
  price !== null &&
  piecesFrom !== null &&
  Number(piecesFrom) > 0
) {
  normalizedUnit = "pcs";

  unitPriceWorstCase = Number(
    (
      Number(price) /
      Number(piecesFrom)
    ).toFixed(4)
  );

  const bestPieces =
    piecesTo !== null &&
    Number(piecesTo) > 0
      ? Number(piecesTo)
      : Number(piecesFrom);

  unitPriceBestCase = Number(
    (
      Number(price) /
      bestPieces
    ).toFixed(4)
  );
}

const hasQuantityRange =
  (
    quantityFrom !== null &&
    quantityTo !== null &&
    Number(quantityFrom) !== Number(quantityTo)
  ) ||
  (
    piecesFrom !== null &&
    piecesTo !== null &&
    Number(piecesFrom) !== Number(piecesTo)
  );

return {
  json: {
    externalOfferId: raw.id,
    chainId: raw.dealer_id,

    chainName:
      raw.branding?.name ??
      raw.dealer?.name ??
      "Unknown",

    productName,
    description,

    priceDkk: price,
    advertisedBeforePriceDkk:
      advertisedBeforePrice,

    quantityFrom,
    quantityTo,
    originalUnit,

    piecesFrom,
    piecesTo,

    unitPriceWorstCase,
    unitPriceBestCase,
    normalizedUnit,

    validFrom:
      raw.run_from ?? null,

    validUntil:
      raw.run_till ?? null,

    imageUrl:
      raw.images?.view ?? null,

    hasQuantityRange,

    rawPayload: raw
  }
};
